import {esc,safeMedia} from './core.js';
export function slideHTML(s,c,index,state={},mediaEnabled=false){
 const footer=`<div class="slide-footer"><span>${esc(c.venue)}</span><span>${String(index+1).padStart(2,'0')} / ${c.slides.length}</span></div>`;
 let content='';
 if(s.media&&safeMedia(s.media.src)){
 const {src,type,alt}=s.media;
 if(type==='image')content=`<div class="slide-media"><img src="${esc(src)}" alt="${esc(alt||s.title)}"></div>`;
 if(type==='video')content=`<div class="slide-media">${mediaEnabled?`<video data-media preload="metadata" playsinline src="${esc(src)}" aria-label="${esc(alt||s.title)}"></video>`:'<div class="audio-art" aria-label="Vidéo"><i style="--h:8cqw"></i><i style="--h:12cqw"></i><i style="--h:8cqw"></i></div>'}</div>`;
 if(type==='audio')content=`<div class="slide-media"><div class="audio-art" aria-label="Extrait audio">${[4,7,11,6,13,8,5,10,14,7,4,9,6,12,5].map(h=>`<i style="--h:${h}cqw"></i>`).join('')}</div>${mediaEnabled?`<audio data-media preload="metadata" src="${esc(src)}"></audio>`:''}</div>`;
 }else if(s.kind==='cards')content=`<div class="slide-cards count-${s.body.length}">${s.body.map(t=>{const [a,...b]=t.split('|');return `<div class="slide-card"><strong>${esc(a)}</strong><p>${esc(b.join('|'))}</p></div>`}).join('')}</div>`;
 else content=`<div class="slide-lines">${s.body.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`;
 return `<article class="slide ${esc(s.kind)} ${s.theme==='dark'?'dark':'light'}" data-slide-id="${esc(s.id)}">${s.kind==='media'?'':`<div class="slide-top">${esc(c.venue)}${s.bonus?' · BONUS':''}</div><h2 class="slide-title">${esc(s.title)}</h2><p class="slide-subtitle">${esc(s.subtitle)}</p>`}${content}${s.kind==='media'?'':footer}${state.revealed&&s.answer?`<div class="reveal-cover"><h2>${esc(s.answer)}</h2><p>${esc(s.explanation||'')}</p><small>${esc(s.source||'Exercice pédagogique préparé')}</small></div>`:''}${state.activityEnd?'<div class="timer-overlay" data-activity></div>':''}${state.black?'<div class="black-cover" aria-label="Écran noir"></div>':''}</article>`;
}
export const icons={screen:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M8 21h8M12 16v5"/>',next:'<path d="m9 5 7 7-7 7"/>',prev:'<path d="m15 5-7 7 7 7"/>',play:'<path d="m8 4 12 8-12 8Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',edit:'<path d="m15 4 5 5-11 11H4v-5Z M13 6l5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 4v16M4 12h16"/>',black:'<rect x="3" y="4" width="18" height="15" rx="2" fill="currentColor"/>',volume:'<path d="m3 9 4 0 5-5v16l-5-5H3ZM16 8q5 4 0 8M19 4q9 8 0 16"/>',link:'<path d="m10 14 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>'};
export const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||''}</svg>`;
export const btn=(action,label,ic='',cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${ic?icon(ic):''}${label}</button>`;
